create database customer_behaviour;
use customer_behaviour;
select * from cleaned_data limit 20;

-- what is total revenue generated by male and women.
select gender, sum(purchase_usd) as revenue
from cleaned_data
group by gender;

-- which customer use discount coupoun but still spent more than usual amount.
select customer_id , purchase_usd
from cleaned_data
where discount_applied = 'Yes' and purchase_usd >= (select avg(purchase_usd) from cleaned_data);

-- which top 5 products with the highest average rating.
select item_purchased , round(avg(review_rating),2) as "product_rating"
from cleaned_data
group by item_purchased
order by avg(review_rating) desc limit 5;

-- compare average amount between standard nd express shipping
select shipping_type, 
round(Avg(purchase_usd),2) as shipping_by_revenue from cleaned_data
where shipping_type in ('Standard','Express')
group by shipping_type;

-- do subscribe people spend more compare average spend and total revenue between subs and no subs
select subscription_status, round(avg(customer_id)) as total_spend,
round(sum(purchase_usd),2) as total_rev
from cleaned_data
group by subscription_status 
order by total_spend, total_rev desc;

-- which top 5 products has highest purchase with discount_applied
select item_purchased,
round(100 * sum(case when discount_applied= 'yes' then 1 else 0 end)/ count(*),2) as discount_rate
from cleaned_data
group by item_purchased 
order by discount_rate desc limit 5 ;

-- segement customers new, returning and loyal by their number of purchases and show count of segment
with customer_type as (
select customer_id,previous_purchases,
case when previous_purchases = 1 then 'new'
when previous_purchases between 2 and 10 then 'returning'
else 'loyal' end as customer_segment
from  cleaned_data
)
select customer_segment, count(*) as 'no of customer'
from customer_type
group by customer_segment;

-- what are top 3 purchase proudct in each category
with item_counts as (
select category, item_purchased,
count(customer_id) as total_orders,
row_number() over(partition by category order by count(customer_id) desc) as item_rank
from cleaned_data
group by category, item_purchased
)
select item_rank,category,item_purchased,total_orders
from item_counts
where item_rank <= 3;

-- are customers who are repeat buyers also can convert to subscribed people more than 5 purchased
select subscription_status,
count(customer_id) as repeat_buyer
from cleaned_data
where previous_purchases > 5
group by subscription_status;

-- total revenue by the each age group
SELECT 
    age_group, SUM(purchase_usd) AS total_revenue
FROM
    cleaned_data
GROUP BY age_group
ORDER BY total_revenue DESC;